/* App shell: header, sidebar navigation, footer, and chrome controls. */

.header {
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border);
  padding: 16px 32px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: sticky;
  top: 0;
  z-index: 100;
}
.header h1 { font-family: var(--font-display); font-size: 20px; font-weight: 800; letter-spacing: -0.5px; background: var(--accent-gradient); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text; }
.logo-link { text-decoration: none; }
.header-info { display: flex; gap: 16px; font-size: 13px; color: var(--text-secondary); align-items: center; flex-wrap: wrap; }
.header-info .label { color: var(--text-muted); margin-right: 4px; }
.header-group { display: flex; align-items: center; gap: 8px; }
.header-divider { width: 1px; height: 20px; background: var(--border); flex-shrink: 0; }
[data-theme="light"] .header { box-shadow: 0 1px 4px rgba(0,0,0,0.06); border-bottom-color: transparent; }
.settings-btn:hover { background: var(--bg-hover); }

/* Header/settings toggles */
.sex-toggle { display: flex; align-items: center; gap: 4px; }
.sex-toggle-btn {
  padding: 4px 10px; border-radius: 6px; border: 1px solid var(--border);
  background: transparent; color: var(--text-secondary); font-size: 14px;
  cursor: pointer; font-weight: 500; transition: all 0.15s; font-family: inherit;
  line-height: 1;
}
.sex-toggle-btn.active { background: var(--accent); color: white; border-color: var(--accent); }
.sex-toggle-btn:hover:not(.active) { background: var(--bg-hover); }
.dob-input { display: flex; align-items: center; gap: 6px; }
.dob-input label { font-size: 12px; color: var(--text-muted); font-weight: 500; }
.dob-input input[type="date"] {
  padding: 4px 8px; border-radius: 6px; border: 1px solid var(--border);
  background: transparent; color: var(--text-secondary); font-size: 12px;
  font-family: inherit; cursor: pointer; transition: all 0.15s;
  color-scheme: dark;
}
.dob-input input[type="date"]:focus { border-color: var(--accent); color: var(--text-primary); }
.dob-input input[type="date"]::-webkit-calendar-picker-indicator { filter: invert(0.6); cursor: pointer; }
[data-theme="light"] .dob-input input[type="date"] { color-scheme: light; }
[data-theme="light"] .dob-input input[type="date"]::-webkit-calendar-picker-indicator { filter: none; }
.unit-toggle { display: flex; align-items: center; gap: 4px; }
.unit-toggle-btn {
  padding: 4px 12px; border-radius: 6px; border: 1px solid var(--border);
  background: transparent; color: var(--text-secondary); font-size: 12px;
  cursor: pointer; font-weight: 500; transition: all 0.15s; font-family: inherit;
}
.unit-toggle-btn.active { background: var(--accent); color: white; border-color: var(--accent); }
.unit-toggle-btn:hover:not(.active) { background: var(--bg-hover); }
.time-toggle-btn {
  padding: 4px 12px; border-radius: 6px; border: 1px solid var(--border);
  background: transparent; color: var(--text-secondary); font-size: 12px;
  cursor: pointer; transition: all 0.15s;
}
.time-toggle-btn.active { background: var(--accent); color: var(--on-accent); border-color: var(--accent); }
.time-toggle-btn:hover:not(.active) { background: var(--bg-hover); }
.range-toggle { display: flex; align-items: center; gap: 4px; }
.range-toggle-btn {
  padding: 4px 12px; border-radius: 6px; border: 1px solid var(--border);
  background: transparent; color: var(--text-secondary); font-size: 12px;
  cursor: pointer; font-weight: 500; transition: all 0.15s; font-family: inherit;
}
.range-toggle-btn.active { background: var(--accent); color: var(--on-accent); border-color: var(--accent); }
.range-toggle-btn:hover:not(.active) { background: var(--bg-hover); }

/* Notification Toast */
.notification-container {
  position: fixed; top: 72px; right: 24px; z-index: 350;
  display: flex; flex-direction: column; gap: 8px;
  max-width: calc(100vw - 48px);
}
.notification-toast {
  background: var(--bg-secondary); border: 1px solid var(--border);
  border-radius: var(--radius-sm); padding: 12px 20px;
  font-size: 13px; color: var(--text-primary); min-width: 280px;
  box-shadow: var(--shadow-lg); animation: toastIn 0.3s ease;
  display: flex; align-items: center; gap: 8px;
  position: relative; overflow: hidden;
}
.notification-toast::after {
  content: ''; position: absolute; bottom: 0; left: 0; height: 2px; width: 100%;
  animation: toastProgress 3s linear forwards;
}
.notification-toast.success { border-left: 3px solid var(--green); }
.notification-toast.success::after { background: var(--green); }
.notification-toast.error { border-left: 3px solid var(--red); }
.notification-toast.error::after { background: var(--red); }
.notification-toast.info { border-left: 3px solid var(--accent); }
.notification-toast.info::after { background: var(--accent); }
@keyframes toastIn { from { transform: translateX(100%); opacity:0; } to { transform:translateX(0); opacity:1; } }
@keyframes toastProgress { from { width: 100%; } to { width: 0%; } }

/* Guided Tour */

/* First-launch analytics transparency banner - fixed bottom-center, dismisses forever */
.analytics-consent-banner {
  position: fixed; left: 50%; bottom: 18px; transform: translateX(-50%);
  z-index: 1000; max-width: min(640px, calc(100vw - 24px));
  display: flex; gap: 12px; align-items: center; flex-wrap: wrap;
  background: var(--bg-secondary, #1a1d24); border: 1px solid var(--border, #2d3138);
  border-radius: 10px; padding: 10px 14px;
  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.32);
  animation: analytics-consent-in 0.25s ease-out;
}
@keyframes analytics-consent-in {
  from { opacity: 0; transform: translate(-50%, 12px); }
  to   { opacity: 1; transform: translate(-50%, 0); }
}
.analytics-consent-body { display: flex; gap: 8px; align-items: center; font-size: 12px; color: var(--text-secondary); line-height: 1.45; flex: 1 1 280px; min-width: 0; }
.analytics-consent-body strong { color: var(--text-primary); }
.analytics-consent-copy-short { display: none; }
.analytics-consent-actions { display: flex; gap: 6px; flex: 0 0 auto; }
.analytics-consent-btn { font-size: 12px; padding: 4px 12px; border-radius: 6px; border: 1px solid var(--border); background: transparent; color: var(--text-secondary); cursor: pointer; transition: background 0.15s, border-color 0.15s, color 0.15s; }
.analytics-consent-btn:hover { background: var(--bg-elevated, rgba(255,255,255,0.04)); color: var(--text-primary); border-color: var(--text-muted); }
.analytics-consent-btn-primary { background: var(--accent); border-color: var(--accent); color: var(--on-accent); }
.analytics-consent-btn-primary:hover { filter: brightness(1.08); background: var(--accent); color: var(--on-accent); }

/* Version update prompt - user-controlled service-worker activation */
.version-update-banner {
  position: fixed; left: 50%; bottom: 18px; transform: translateX(-50%);
  z-index: 1001; max-width: min(560px, calc(100vw - 24px));
  display: flex; gap: 12px; align-items: center; flex-wrap: wrap;
  background: var(--bg-secondary, #1a1d24); border: 1px solid var(--border, #2d3138);
  border-radius: 10px; padding: 10px 14px;
  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.32);
  animation: analytics-consent-in 0.25s ease-out;
}
.version-update-body { display: grid; gap: 6px; font-size: 12px; color: var(--text-secondary); line-height: 1.45; flex: 1 1 240px; min-width: 0; }
.version-update-body strong { color: var(--text-primary); }
.version-update-copy-row { display: flex; gap: 12px; align-items: center; justify-content: space-between; min-width: 0; }
.version-update-copy { min-width: 0; }
.version-update-percent { flex: 0 0 auto; color: var(--accent); font-family: var(--font-mono); font-size: 10px; font-weight: 700; font-variant-numeric: tabular-nums; }
.version-update-progress[hidden], .version-update-actions[hidden] { display: none; }
.version-update-progress { display: grid; gap: 4px; width: 100%; }
.version-update-progress-track { height: 7px; overflow: hidden; border: 1px solid color-mix(in srgb, var(--accent) 34%, var(--border)); border-radius: 999px; background: color-mix(in srgb, var(--accent) 7%, var(--bg-secondary)); }
.version-update-progress-fill { display: block; width: 0; height: 100%; border-radius: inherit; background: linear-gradient(90deg, color-mix(in srgb, var(--accent) 72%, var(--green)), var(--accent)); box-shadow: 0 0 10px color-mix(in srgb, var(--accent) 35%, transparent); transition: width .2s ease; }
.version-update-progress-meta { overflow: hidden; color: var(--text-muted); font-family: var(--font-mono); font-size: 8px; font-variant-numeric: tabular-nums; text-overflow: ellipsis; white-space: nowrap; }
.version-update-actions { display: flex; gap: 6px; flex: 0 0 auto; }
.version-update-btn { font-size: 12px; padding: 4px 12px; border-radius: 6px; border: 1px solid var(--border); background: transparent; color: var(--text-secondary); cursor: pointer; transition: background 0.15s, border-color 0.15s, color 0.15s; }
.version-update-btn:hover { background: var(--bg-elevated, rgba(255,255,255,0.04)); color: var(--text-primary); border-color: var(--text-muted); }
.version-update-btn-primary { background: var(--accent); border-color: var(--accent); color: var(--on-accent); }
.version-update-btn-primary:hover { filter: brightness(1.08); background: var(--accent); color: var(--on-accent); }
body.analytics-consent-visible .version-update-banner { bottom: 78px; }
@media (prefers-reduced-motion: reduce) {
  .version-update-progress-fill { transition: none; }
}

/* Terms/Privacy acceptance gate */
.modal-overlay.legal-consent-overlay {
  z-index: 4200;
  align-items: center;
  justify-content: center;
  padding: 18px;
  -webkit-backdrop-filter: blur(8px);
  backdrop-filter: blur(8px);
}
.legal-consent-modal {
  width: min(620px, 100%);
  max-height: 100%;
  overflow-y: auto;
  overscroll-behavior: contain;
  touch-action: pan-y;
  -webkit-overflow-scrolling: touch;
  background: var(--bg-secondary, #171a22);
  border: 1px solid var(--border, #2d3138);
  border-radius: 18px;
  padding: 24px;
  box-shadow: 0 24px 80px rgba(0, 0, 0, 0.5);
  color: var(--text-primary);
}
.legal-consent-kicker {
  font-family: var(--font-mono);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: .12em;
  color: var(--accent);
  margin-bottom: 8px;
}
.legal-consent-modal h2 { margin: 0 0 10px; font-size: 24px; }
.legal-consent-copy { color: var(--text-secondary); line-height: 1.55; margin: 0 0 16px; }
.legal-consent-summary {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  margin: 0 0 14px;
}
.legal-consent-summary > div {
  padding: 10px 12px;
  background: var(--bg-card, rgba(255,255,255,.04));
  border: 1px solid var(--border);
  border-radius: 10px;
  color: var(--text-secondary);
  font-size: 13px;
}
.legal-consent-summary strong { color: var(--text-primary); }
.legal-consent-points {
  margin: 0 0 16px 18px;
  padding: 0;
  color: var(--text-secondary);
  font-size: 13px;
  line-height: 1.55;
}
.legal-consent-check {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  padding: 13px 14px;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--bg-primary, rgba(0,0,0,.18));
  color: var(--text-secondary);
  line-height: 1.45;
}
.legal-consent-check input { margin-top: 3px; accent-color: var(--accent); }
.legal-consent-check a {
  color: var(--accent);
  text-decoration: underline;
  text-underline-offset: .16em;
}
.cloud-ai-consent-links {
  margin: 10px 2px 0;
  font-size: 12px;
}
.cloud-ai-consent-links a { color: var(--accent); }
.legal-consent-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 18px;
}
.cloud-ai-consent-cancel {
  border: 1px solid var(--border);
  background: transparent;
  color: var(--text-secondary);
  border-radius: 9px;
  padding: 9px 16px;
  font-weight: 600;
  cursor: pointer;
}
.cloud-ai-consent-cancel:hover {
  border-color: var(--text-muted);
  color: var(--text-primary);
}
.legal-consent-link { font-size: 13px; margin-right: auto; }
.legal-consent-link + .legal-consent-link { margin-right: 0; }
.legal-consent-accept {
  border: 1px solid var(--accent);
  background: var(--accent);
  color: var(--on-accent);
  border-radius: 9px;
  padding: 9px 16px;
  font-weight: 700;
  cursor: pointer;
}
.legal-consent-accept:disabled {
  opacity: .45;
  cursor: not-allowed;
  filter: grayscale(.35);
}
@media (max-width: 640px) {
  .legal-consent-modal { padding: 18px; border-radius: 14px; }
  .legal-consent-summary { grid-template-columns: 1fr; }
  .legal-consent-actions { justify-content: stretch; }
  .legal-consent-link { margin-right: 0; }
  .cloud-ai-consent-links a { display: inline-flex; align-items: center; min-height: 32px; }
  .legal-consent-accept,
  .cloud-ai-consent-cancel { width: 100%; min-height: 44px; }
}

.layout { display: flex; min-height: calc(100vh - 57px); }
.sidebar {
  width: 260px;
  background: var(--bg-secondary);
  border-right: 1px solid var(--border);
  padding: 18px 12px;
  overflow-y: auto;
  overscroll-behavior: contain;
  position: fixed;
  top: 57px;
  left: 0;
  height: calc(100vh - 57px);
  z-index: 10;
}
[data-theme="light"] .sidebar { box-shadow: 1px 0 4px rgba(0,0,0,0.04); border-right-color: transparent; }

.sidebar-search-wrap {
  position: relative;
  margin: 0 4px 18px;
}
.sidebar-search-icon {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--text-muted);
  font-family: var(--font-mono);
  font-size: 14px;
  pointer-events: none;
}
.sidebar-search {
  width: calc(100% - 32px);
  margin: 4px 16px 8px;
  padding: 8px 12px;
  border-radius: 6px;
  border: 1px solid var(--border);
  background: var(--bg-primary);
  color: var(--text-primary);
  font-size: 13px;
  font-family: inherit;
}
.sidebar-search:focus { border-color: var(--accent); }
.sidebar-search::placeholder { color: var(--text-muted); }
.sidebar-search-wrap .sidebar-search {
  width: 100%;
  margin: 0;
  padding: 10px 12px 10px 36px;
  border-radius: var(--radius-sm);
}
.nav-section {
  margin: 16px 8px 8px;
  color: var(--text-muted);
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}
.sidebar-title {
  display: flex; align-items: center; justify-content: space-between; gap: 8px;
  padding: 0 8px;
}
.nav-item {
  display: flex; align-items: center; gap: 10px; padding: 8px 12px;
  min-height: 36px;
  cursor: pointer; font-size: 14px; color: var(--text-secondary);
  transition: all 0.15s; border: 1px solid transparent;
  border-radius: var(--radius-sm);
  background: transparent;
}
.nav-item:hover { background: var(--bg-hover); color: var(--text-primary); }
.nav-item.active,
.nav-item.is-active {
  background: var(--bg-card); color: var(--text-primary);
  border-color: var(--border); font-weight: 600;
}
.nav-item.active .nav-item-dot,
.nav-item.is-active .nav-item-dot {
  background: var(--accent);
}
.nav-item-icon {
  width: 16px;
  color: var(--text-muted);
  font-family: var(--font-mono);
  font-size: 13px;
  text-align: center;
  flex-shrink: 0;
}
.nav-item.active .nav-item-icon { color: var(--accent); }
.nav-item-dot {
  width: 8px; height: 8px;
  border-radius: 50%;
  background: var(--border);
  flex-shrink: 0;
}
.nav-item-label {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.nav-item .count,
.nav-item-count {
  margin-left: auto; font-size: 11px; background: var(--bg-primary);
  padding: 1px 7px; border-radius: 4px; color: var(--text-muted);
  border: 1px solid var(--border);
  font-family: var(--font-mono);
}
.nav-item .flag-count {
  margin-left: auto; font-family: var(--font-mono); font-size: 11px; background: var(--red-bg);
  padding: 1px 7px; border-radius: 4px; color: var(--red); font-weight: 700;
  box-shadow: 0 0 6px rgba(248, 113, 113, 0.15);
}
.nav-item .nav-count {
  margin-left: auto; font-size: 11px; background: var(--bg-card);
  padding: 1px 7px; border-radius: 10px; color: var(--text-muted);
}
.sidebar-group-header {
  display: flex; align-items: center; gap: 8px; padding: 8px 12px; margin-top: 8px;
  font-size: 11px; font-weight: 600; text-transform: uppercase;
  letter-spacing: 1px; color: var(--text-muted); user-select: none;
  /* Mouse-only click affordance - onclick on the outer div fires
     toggleNavGroup, the toggle button + AI button stopPropagation. No
     role / tabindex so axe doesn't flag it as a nested-interactive
     parent of the inner buttons. */
  cursor: pointer;
}
/* The disclosure toggle wears the row's keyboard interactivity (axe
   nested-interactive). Content-sized - NOT flex:1 - so the AI sibling
   button sits adjacent to the flag count, and the arrow's margin-left:
   auto pushes it to the far right. The outer div carries an onclick
   too (no role/tabindex, so axe ignores it) - covers the gap so mouse
   users can click anywhere on the row to toggle. */
.sidebar-group-toggle {
  display: flex; align-items: center; gap: 8px;
  background: none; border: 0; padding: 0; margin: 0;
  font: inherit; color: inherit; text-align: left;
  text-transform: inherit; letter-spacing: inherit;
  cursor: pointer;
}
.sidebar-group-toggle:hover { color: var(--text-secondary); }
.sidebar-group-toggle:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; border-radius: 4px; }
.sidebar-group-header .flag-count {
  font-family: var(--font-mono); font-size: 10px; background: var(--red-bg);
  padding: 0 5px; border-radius: 8px; color: var(--red); font-weight: 600;
}
.sidebar-group-arrow {
  margin-left: auto; font-size: 10px; transition: transform 0.15s;
}
.sidebar-group-header:not(.collapsed) .sidebar-group-arrow { transform: rotate(90deg); }
.sidebar-add-marker {
  float: right; width: 20px; height: 20px; border-radius: 4px; border: 1px solid var(--border);
  background: transparent; color: var(--text-muted); font-size: 14px; line-height: 18px; cursor: pointer;
  padding: 0; font-family: inherit; transition: all 0.15s;
}
.sidebar-add-marker:hover { border-color: var(--accent); color: var(--accent); background: rgba(79,140,255,0.08); }

.main { flex: 1; min-height: calc(100vh - 57px + 180px); padding: 24px 32px; margin-left: 260px; max-width: calc(100vw - 260px); }

.app-footer { border-top: 1px solid var(--border); padding: 56px 32px 40px; margin-left: 260px; }
.app-footer-row { max-width: 1200px; margin: 0 auto; display: flex; justify-content: space-between; align-items: center; gap: 24px; }
.app-footer-row.app-footer-top { padding-bottom: 24px; border-bottom: 1px solid var(--border); margin-bottom: 24px; }
.app-footer-logo { font-family: var(--font-display); font-weight: 800; font-size: 18px; background: var(--accent-gradient); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text; }
.app-footer-socials { display: flex; gap: 16px; align-items: center; }
.app-footer-socials a { color: var(--text-muted); transition: color 0.2s; display: inline-flex; }
.app-footer-socials a:hover { color: var(--text-primary); }
.app-footer-version { font-size: 11px; color: var(--text-muted); font-family: var(--font-mono); }
.app-footer-version a { color: var(--text-muted); text-decoration: none; }
.app-footer-version a:hover { color: var(--accent); text-decoration: underline; }
.app-footer-fineprint {
  max-width: 1200px; margin: 0 auto;
  display: flex; flex-direction: column; align-items: center; gap: 10px;
  text-align: center;
}
.app-footer-disclaimer {
  font-size: 11.5px; color: var(--text-secondary); line-height: 1.55; margin: 0; letter-spacing: 0.01em;
}
.app-footer-trademarks {
  font-size: 10.5px; color: var(--text-muted);
  line-height: 1.55; margin: 0; max-width: 760px; letter-spacing: 0.01em;
}
.app-footer-legal {
  font-size: 11.5px; color: var(--text-muted); margin: 0;
  display: flex; flex-wrap: wrap; gap: 8px 14px;
  justify-content: center; align-items: center;
}
.app-footer-legal a { color: var(--text-muted); text-decoration: none; transition: color 0.15s; }
.app-footer-legal a:hover { color: var(--accent); }
.app-footer-sep { opacity: 0.5; }

.sync-indicator {
  background: transparent; border: none; cursor: pointer; padding: 6px 8px;
  display: inline-flex; align-items: center; justify-content: center; line-height: 1;
}
.sync-dot {
  width: 8px; height: 8px; border-radius: 50%; display: inline-block; transition: background 0.3s;
}
.sync-dot-synced { background: var(--green); }
.sync-dot-syncing { background: var(--accent); animation: sync-pulse 1.5s ease-in-out infinite; }
.sync-dot-offline { background: var(--yellow); }
.sync-dot-error { background: var(--red); }
@keyframes sync-pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.3; } }
.sync-popover {
  position: absolute; top: 100%; right: 0; z-index: 999;
  background: var(--sync-popover-bg, var(--bg-card)); color: var(--text-primary);
  border: 1px solid var(--border); border-radius: var(--radius);
  padding: 14px 16px; min-width: 220px; box-shadow: var(--shadow-lg);
  margin-top: 6px;
}
/* Header icon buttons (Settings, Feedback, Donate). Was historically named
   .glossary-btn - the marker glossary feature was retired in v1.3.25, but
   the styling primitive was the standard for top-bar icon buttons. */
.header-icon-btn {
  background: transparent; border: 1px solid var(--border); color: var(--text-secondary);
  padding: 6px 10px; border-radius: var(--radius-sm); cursor: pointer; font-size: 16px;
