@media (max-width: 768px), (pointer: coarse) {
  .logo-link {
    display: inline-flex;
    align-items: center;
    min-height: 44px;
  }
  .header-share-btn {
    display: none;
  }
  .dashboard-widget-tool,
  .lens-widget-dashboard-toggle {
    min-width: 44px;
    min-height: 44px;
    height: auto;
    padding: 0 12px;
    line-height: 1.25;
  }
  .lens-widget-dashboard-toggle {
    padding-inline: 14px;
  }
  .analytics-consent-btn {
    min-width: 44px;
    min-height: 44px;
    padding: 8px 12px;
  }
