/* Loaded immediately before Chat opens, after the eager redesign shell. */
.chat-panel.open {
  transform: translateX(0);
}
.chat-panel.chat-panel-fullscreen {
  width: 100vw;
}
body.chat-open .main {
  padding-right: calc(32px + min(var(--chat-panel-current-width, 600px), 100vw));
}
body.chat-open.chat-fullscreen .main {
  padding-right: 32px;
}
body.chat-open .analytics-consent-banner {
  transform: none;
  z-index: 220;
  animation: none;
}
@media (min-width: 769px) {
  body.chat-open .analytics-consent-banner {
    left: 18px;
    right: auto;
    transform: none;
    max-width: min(640px, calc(100vw - 520px));
  }
}
.chat-panel-conversation {
  background: var(--bg-secondary);
  position: relative;
}


.chat-thread-new-btn,
.chat-project-new-btn {
  border-radius: var(--radius-sm);
}

.chat-rail-back svg,
.chat-thread-new-btn svg {
  display: block;
  width: 16px;
  height: 16px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.chat-thread-rail {
  background: var(--bg-primary);
}
.chat-thread-rail.open {
  width: var(--chat-rail-width, 220px);
}
.chat-messages {
  padding: 18px;
  gap: 14px;
}
.chat-msg:not([data-chat-transcript-message], [data-chat-onboarding-message]) {
  max-width: 85%;
  padding: 12px 14px;
  border-radius: var(--radius);
  font-size: 14px;
  line-height: 1.58;
}
.chat-msg.chat-ai:not([data-chat-transcript-message], [data-chat-onboarding-message]) {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-left: 1px solid color-mix(in srgb, var(--accent) 55%, var(--border));
  border-bottom-left-radius: var(--radius-sm);
}
.chat-msg.chat-user:not([data-chat-transcript-message], [data-chat-onboarding-message]) {
  color: var(--on-accent);
  border-bottom-right-radius: var(--radius-sm);
}
.chat-user a {
  color: var(--on-accent);
}
.chat-prompt-btn:where(:not([data-chat-provider-setup-view] *, [data-chat-empty-view] *)),
.chat-quiz-option:where(:not([data-chat-provider-view], [data-chat-provider-view] *)),
.chat-setup-btn:where(:not([data-chat-provider-view], [data-chat-provider-view] *)),
.chat-onboard-cta:where(:not([data-chat-provider-setup-view] *, [data-chat-empty-view] *)) {
  border-radius: var(--radius-sm);
}
.chat-msg.chat-ai:not([data-chat-onboarding-message]):has(.chat-quiz-options),
.chat-msg.chat-ai:not([data-chat-onboarding-message]):has(.chat-onboard-actions) {
  align-self: stretch;
  width: 100% !important;
  max-width: 100%;
  box-sizing: border-box;
  padding: 16px;
  border-left: 1px solid var(--border);
  border-bottom-left-radius: var(--radius);
  background: color-mix(in srgb, var(--bg-card) 86%, var(--bg-secondary));
}
.chat-onboard-input:where(:not([data-chat-profile-setup-view] *)) {
  min-height: 38px;
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
}
.chat-onboard-cta:where(:not([data-chat-provider-setup-view] *, [data-chat-empty-view] *)),
.chat-setup-btn:where(:not([data-chat-provider-view], [data-chat-provider-view] *)),
.chat-quiz-option:where(:not([data-chat-provider-view], [data-chat-provider-view] *)) {
  min-height: 38px;
}
.chat-panel.chat-onboarding-active .chat-msg.chat-ai:not([data-chat-onboarding-message]),
.chat-panel.chat-onboarding-active .chat-msg.chat-ai:not([data-chat-onboarding-message]):has(.chat-quiz-options),
.chat-panel.chat-onboarding-active .chat-msg.chat-ai:not([data-chat-onboarding-message]):has(.chat-onboard-actions) {
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--bg-card) 94%, transparent), color-mix(in srgb, var(--bg-secondary) 74%, transparent)),
    var(--bg-primary);
}
.chat-panel.chat-onboarding-active .chat-quiz-option:where(:not([data-chat-provider-view], [data-chat-provider-view] *)) {
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--bg-card) 82%, transparent), color-mix(in srgb, var(--bg-secondary) 58%, transparent)),
    var(--bg-primary);
}

@media (min-width: 1400px) {
  /* Keep the dashboard reservation coupled to the live panel width. A fixed
     desktop value makes widths above 600px overlap the dashboard while the
     user drags the resize handle or opens the conversation rail. */
  body.chat-open .main { padding-right: calc(32px + min(var(--chat-panel-current-width, 600px), 100vw)); }
  body.chat-open.chat-fullscreen .main { padding-right: 32px; }
  .chat-messages { padding: 18px; gap: 14px; }

  .chat-msg:not([data-chat-transcript-message], [data-chat-onboarding-message]) { font-size: 14px; padding: 12px 14px; }
}
@media (max-width: 768px) {
  body.chat-open .m-tabbar {
    display: none;
  }
  body.chat-open .main { padding-right: 0; }
  body.chat-open.chat-fullscreen .main { padding-right: 0; }

  .chat-messages { padding: 14px 12px; }
  .chat-msg:not([data-chat-transcript-message], [data-chat-onboarding-message]) { max-width: 92%; }
  .chat-msg.chat-ai:not([data-chat-onboarding-message]):has(.chat-quiz-options),
  .chat-msg.chat-ai:not([data-chat-onboarding-message]):has(.chat-onboard-actions) {
    padding: 14px;
  }
  .chat-panel.chat-onboarding-active .chat-messages {
    padding-bottom: calc(20px + env(safe-area-inset-bottom));
  }

  .chat-thread-rail.open {
    position: absolute;
    inset: 0;
    width: 100%;
    z-index: 10;
    border-right: 0;
    background: var(--bg-secondary);
    box-shadow: none;
  }
  .chat-thread-rail.open .chat-thread-rail-header {
    min-height: 60px;
    padding: 12px 16px;
    border-bottom: 1px solid var(--border);
  }
  .chat-thread-rail.open .chat-rail-back,
  .chat-thread-new-btn {
    width: 38px;
    height: 38px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
  }
  .chat-thread-search {
    min-height: 44px;
    margin: 12px 14px;
    padding: 9px 12px;
    border-radius: var(--radius-sm);
    font-size: 14px;
  }
  .chat-thread-list {
    padding: 0 12px 16px;
  }

}
.chat-panel.chat-panel-fullscreen,
.chat-panel.chat-panel-fullscreen:has(.chat-thread-rail.open) {
  left: 0;
  right: 0;
  width: 100vw;
  max-width: none;
}
.chat-panel.chat-panel-fullscreen .chat-messages {
  padding-inline: clamp(18px, 2.5vw, 48px);
}
.chat-panel.chat-panel-fullscreen .chat-msg.chat-ai:not([data-chat-transcript-message], [data-chat-onboarding-message]),
.chat-panel.chat-panel-fullscreen .chat-msg.chat-ai:not([data-chat-onboarding-message]):has(.chat-quiz-options),
.chat-panel.chat-panel-fullscreen .chat-msg.chat-ai:not([data-chat-onboarding-message]):has(.chat-onboard-actions) {
  width: 100% !important;
  max-width: 100%;
}
.chat-panel.chat-panel-fullscreen .chat-msg.chat-ai.chat-avatar-anchor:not([data-chat-transcript-message], [data-chat-onboarding-message]) {
  width: calc(100% - 36px) !important;
  max-width: calc(100% - 36px);
}
.chat-panel.chat-panel-fullscreen .chat-msg.chat-user:not([data-chat-transcript-message], [data-chat-onboarding-message]) {
  max-width: min(100%, 1120px);
}
body.chat-open.chat-fullscreen:has(#chat-thread-rail.open) .main {
  padding-right: 32px;
}
@media (max-width: 768px) {
  .chat-panel:has(.chat-thread-rail.open) .chat-thread-rail.open { width: 100%; }
  body.chat-open:has(#chat-thread-rail.open) .main { padding-right: 0; }
}

/* The Svelte splitters own their visuals; this body state also disables
   transitions on the adjacent shell during a live resize. */
@media (min-width: 769px) {
  body.chat-layout-resizing { cursor: col-resize; user-select: none; }
  body.chat-layout-resizing .chat-panel,
  body.chat-layout-resizing .chat-thread-rail { transition: none !important; }
}
